1	import { createHmac, timingSafeEqual } from "node:crypto";
2	
3	interface JwtHeader {
4	  alg: string;
5	  typ?: string;
6	}
7	
8	export interface LocalAgentJwtClaims {
9	  sub: string;
10	  company_id: string;
11	  adapter_type: string;
12	  run_id: string;
13	  iat: number;
14	  exp: number;
15	  iss?: string;
16	  aud?: string;
17	  jti?: string;
18	}
19	
20	const JWT_ALGORITHM = "HS256";
21	
22	function parseNumber(value: string | undefined, fallback: number) {
23	  const parsed = Number(value);
24	  if (!Number.isFinite(parsed) || parsed <= 0) return fallback;
25	  return Math.floor(parsed);
26	}
27	
28	function jwtConfig() {
29	  const secret = process.env.PAPERCLIP_AGENT_JWT_SECRET?.trim() || process.env.BETTER_AUTH_SECRET?.trim();
30	  if (!secret) return null;
31	
32	  return {
33	    secret,
34	    ttlSeconds: parseNumber(process.env.PAPERCLIP_AGENT_JWT_TTL_SECONDS, 60 * 60 * 48),
35	    issuer: process.env.PAPERCLIP_AGENT_JWT_ISSUER ?? "paperclip",
36	    audience: process.env.PAPERCLIP_AGENT_JWT_AUDIENCE ?? "paperclip-api",
37	  };
38	}
39	
40	function base64UrlEncode(value: string) {
41	  return Buffer.from(value, "utf8").toString("base64url");
42	}
43	
44	function base64UrlDecode(value: string) {
45	  return Buffer.from(value, "base64url").toString("utf8");
46	}
47	
48	function signPayload(secret: string, signingInput: string) {
49	  return createHmac("sha256", secret).update(signingInput).digest("base64url");
50	}
51	
52	function parseJson(value: string): Record<string, unknown> | null {
53	  try {
54	    const parsed = JSON.parse(value);
55	    return parsed && typeof parsed === "object" ? parsed as Record<string, unknown> : null;
56	  } catch {
57	    return null;
58	  }
59	}
60	
61	function safeCompare(a: string, b: string) {
62	  const left = Buffer.from(a);
63	  const right = Buffer.from(b);
64	  if (left.length !== right.length) return false;
65	  return timingSafeEqual(left, right);
66	}
67	
68	export function createLocalAgentJwt(agentId: string, companyId: string, adapterType: string, runId: string) {
69	  const config = jwtConfig();
70	  if (!config) return null;
71	
72	  const now = Math.floor(Date.now() / 1000);
73	  const claims: LocalAgentJwtClaims = {
74	    sub: agentId,
75	    company_id: companyId,
76	    adapter_type: adapterType,
77	    run_id: runId,
78	    iat: now,
79	    exp: now + config.ttlSeconds,
80	    iss: config.issuer,
81	    aud: config.audience,
82	  };
83	
84	  const header = {
85	    alg: JWT_ALGORITHM,
86	    typ: "JWT",
87	  };
88	
89	  const signingInput = `${base64UrlEncode(JSON.stringify(header))}.${base64UrlEncode(JSON.stringify(claims))}`;
90	  const signature = signPayload(config.secret, signingInput);
91	
92	  return `${signingInput}.${signature}`;
93	}
94	
95	export function verifyLocalAgentJwt(token: string): LocalAgentJwtClaims | null {
96	  if (!token) return null;
97	  const config = jwtConfig();
98	  if (!config) return null;
99	
100	  const parts = token.split(".");
101	  if (parts.length !== 3) return null;
102	  const [headerB64, claimsB64, signature] = parts;
103	
104	  const header = parseJson(base64UrlDecode(headerB64));
105	  if (!header || header.alg !== JWT_ALGORITHM) return null;
106	
107	  const signingInput = `${headerB64}.${claimsB64}`;
108	  const expectedSig = signPayload(config.secret, signingInput);
109	  if (!safeCompare(signature, expectedSig)) return null;
110	
111	  const claims = parseJson(base64UrlDecode(claimsB64));
112	  if (!claims) return null;
113	
114	  const sub = typeof claims.sub === "string" ? claims.sub : null;
115	  const companyId = typeof claims.company_id === "string" ? claims.company_id : null;
116	  const adapterType = typeof claims.adapter_type === "string" ? claims.adapter_type : null;
117	  const runId = typeof claims.run_id === "string" ? claims.run_id : null;
118	  const iat = typeof claims.iat === "number" ? claims.iat : null;
119	  const exp = typeof claims.exp === "number" ? claims.exp : null;
120	  if (!sub || !companyId || !adapterType || !runId || !iat || !exp) return null;
121	
122	  const now = Math.floor(Date.now() / 1000);
123	  if (exp < now) return null;
124	
125	  const issuer = typeof claims.iss === "string" ? claims.iss : undefined;
126	  const audience = typeof claims.aud === "string" ? claims.aud : undefined;
127	  if (issuer && issuer !== config.issuer) return null;
128	  if (audience && audience !== config.audience) return null;
129	
130	  return {
131	    sub,
132	    company_id: companyId,
133	    adapter_type: adapterType,
134	    run_id: runId,
135	    iat,
136	    exp,
137	    ...(issuer ? { iss: issuer } : {}),
138	    ...(audience ? { aud: audience } : {}),
139	    jti: typeof claims.jti === "string" ? claims.jti : undefined,
140	  };
141	}
